import fs from 'node:fs';
import path from 'node:path';
import { REPO_ROOT } from '../helpers';
import { runIn } from './run-in';

/**
 * The Prisma client of a generated project and the schema of its test database, build products its
 * sources read: generated by its own `db:client`, with the dependencies of the workspace, lent to the
 * project for the time of the command.
 */
export function generatePrismaClient(root: string): void {
  const lent = path.join(root, 'node_modules');

  fs.symlinkSync(path.join(REPO_ROOT, 'node_modules'), lent, 'dir');

  try {
    runIn(root, { command: 'npm', args: ['run', '--silent', 'db:client'] });
  } finally {
    fs.unlinkSync(lent);
  }
}
